def format_duration_words(total_minutes):
    h = total_minutes // 60
    m = total_minutes % 60
    parts = []
    if h > 0:
        parts.append(f"{h} hour" if h == 1 else f"{h} hours")
    if m > 0 or total_minutes == 0:
        parts.append(f"{m} minute" if m == 1 else f"{m} minutes")
    return " ".join(parts)

def parse_duration_words(s):
    tokens = s.split()
    total = 0
    i = 0
    while i < len(tokens):
        value = int(tokens[i])
        unit = tokens[i + 1]
        if unit.startswith("hour"):
            total += value * 60
        elif unit.startswith("minute"):
            total += value
        i += 2
    return total

def seconds_between_times(start_hhmmss, end_hhmmss):
    def to_seconds(t):
        hh, mm, ss = map(int, t.split(":"))
        return hh * 3600 + mm * 60 + ss
    start_s = to_seconds(start_hhmmss)
    end_s = to_seconds(end_hhmmss)
    if end_s <= start_s:
        return end_s - start_s + 86400
    return end_s - start_s

def add_months_to_date(y, m, d, n_months):
    def is_leap(yr):
        return yr % 4 == 0 and (yr % 100 != 0 or yr % 400 == 0)

    def days_in_month(yr, mo):
        dim = [31, 29 if is_leap(yr) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return dim[mo - 1]

    total_months = (y * 12 + (m - 1)) + n_months
    ny = total_months // 12
    nm = total_months % 12 + 1
    last_day = days_in_month(ny, nm)
    nd = d if d < last_day else last_day
    return (ny, nm, nd)

