def days_to_end_of_year(y, m, d):
    def is_leap(yr):
        return yr % 4 == 0 and (yr % 100 != 0 or yr % 400 == 0)

    def days_in_month(yr, mo):
        dim = [31, 29 if is_leap(yr) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return dim[mo - 1]

    total_days_in_year = 366 if is_leap(y) else 365
    doy = d
    for month in range(1, m):
        doy += days_in_month(y, month)
    return total_days_in_year - doy
